import { describe, it, expect } from "vitest";
import { nextGeneration } from "./game-of-life.js";

describe("Game of Life", () => {
  it.todo("should return empty array for empty input -- []");
  it.todo(
    "should kill a single isolated live cell from underpopulation -- [(0,0)] becomes []"
  );
  it.todo(
    "should kill live cells with fewer than 2 neighbors (Rule 1 underpopulation) -- [(0,1), (1,1)] becomes []"
  );
  it.todo(
    "should let live cells with 2 or 3 neighbors survive (Rule 2 survival) -- [(0,0), (1,0), (2,0), (1,1)] becomes [(1,0), (1,1)]"
  );
  it.todo(
    "should kill live cells with more than 3 neighbors (Rule 3 overpopulation) -- 3x3 block center (1,1) dies, ring of 8 survives"
  );
  it.todo(
    "should birth dead cells with exactly 3 neighbors (Rule 4 reproduction) -- [(0,0), (1,0), (0,1)] becomes [(0,0), (1,0), (0,1), (1,1)]"
  );
  it.todo(
    "should leave a 2x2 block unchanged (still life) -- [(0,0), (1,0), (0,1), (1,1)] stays the same"
  );
  it.todo(
    "should oscillate a vertical blinker to horizontal (Gen 0 to Gen 1) -- [(0,0), (0,1), (0,2)] becomes [(-1,1), (0,1), (1,1)]"
  );
  it.todo(
    "should oscillate a horizontal blinker back to vertical (Gen 1 to Gen 2) -- [(-1,1), (0,1), (1,1)] becomes [(0,0), (0,1), (0,2)]"
  );
});

